#!/usr/bin/env node
/**
 * Regenerates the downloadable Live TV playlist snapshots in public/.
 *
 * The dynamic endpoints (/playlist.m3u, /playlist-all.m3u, /playlist.xspf) always
 * build the playlist from src/scrapers/onlinestream.js at request time. These static
 * copies exist for clients that need a stable file URL (Smart TV browsers, USB copy,
 * GitHub/jsDelivr CDN) and are regenerated by this script whenever the channel list
 * changes:
 *
 *   node scripts/generate_playlists.js
 */

const fs = require('fs');
const path = require('path');
const { buildM3u, buildXspf } = require('../src/playlists');

const PUBLIC_DIR = path.join(__dirname, '..', 'public');
const HOST_URL = 'https://nuvio-magyar-http.onrender.com';

const TARGETS = [
  {
    file: 'nuvio-magyar-tv.m3u',
    label: 'M3U (1 stream / csatorna)',
    build: () => buildM3u({ allMirrors: false })
  },
  {
    file: 'nuvio-magyar-tv-all-mirrors.m3u',
    label: 'M3U (összes tükör)',
    build: () => buildM3u({ allMirrors: true })
  },
  {
    file: 'nuvio-magyar-tv.xspf',
    label: 'XSPF (1 stream / csatorna)',
    build: () => buildXspf({ allMirrors: false }, { hostUrl: HOST_URL })
  },
  {
    file: 'nuvio-magyar-tv-all-mirrors.xspf',
    label: 'XSPF (összes tükör)',
    build: () => buildXspf({ allMirrors: true }, { hostUrl: HOST_URL })
  }
];

for (const target of TARGETS) {
  const body = target.build();
  const outputPath = path.join(PUBLIC_DIR, target.file);
  fs.writeFileSync(outputPath, body, 'utf8');
  const entries = (body.match(/^#EXTINF|^    <track>/gm) || []).length;
  const sizeKb = (Buffer.byteLength(body) / 1024).toFixed(1);
  console.log(`${target.file.padEnd(38)} ${String(entries).padStart(4)} bejegyzés  ${sizeKb} KB  — ${target.label}`);
}

console.log('\nKész. Dinamikus végpontok: /playlist.m3u, /playlist-all.m3u, /playlist.xspf?mirrors=1');
